// {{{ Intent
// Collect every trip away from home into one album per trip -- the holiday
// album a human would have made by hand, named "<Place> <Year>".
//
// The location-album workflow files each photo under the city its EXIF names,
// which scatters a fortnight in Cyprus over fifteen village albums and drops
// the WhatsApp copies entirely, because sharing strips GPS. Nearly half of
// that trip's assets had no coordinates at all. So a trip is detected from
// the geotagged assets and then claims everything else in its days.
//
// The generated name is a first draft. Immich's geocoder names the villages
// a phone happened to be standing in, not the place a person would say they
// went -- the 2026 Naples trip has no single Sorrento photo in it. So the
// album's identity lives in a marker in its description, never in its name:
// rename it in the web ui and later runs keep filling the same album.
//
// Membership is additive and nothing is ever removed or renamed. Immich
// reports an existing membership as a duplicate, which counts as success, so
// re-running is safe and a crashed run simply converges on the next one.
// }}}

// {{{ Settings
const API = $env.IMMICH_URL ?? 'http://127.0.0.1:8416';
const API_KEY = $env.IMMICH_API_KEY;

// Home is inferred from the library rather than configured: the place with
// the most distinct photographed days. Assets, not days, would elect a
// fortnight's holiday over a year of living somewhere -- Mattsee has 237
// assets across 4 days, home has 496 across 151. IMMICH_HOME_LOCATION
// ("lat,lon" in services.n8n.environment) overrides it if that ever picks
// wrong; nothing sets it today.
const HOME_OVERRIDE = $env.IMMICH_HOME_LOCATION;

const AWAY_KM = 75; // Rosenheim and Munich are errands; Innsbruck is not.
const TRIP_GAP_DAYS = 2; // A day without a photo does not end a holiday.
const MIN_TRIP_DAYS = 2; // An overnight stay, so day trips stay out.
const MIN_TRIP_ASSETS = 5;
const RECENT_WINDOW_DAYS = 45; // Long enough to rebuild any ongoing trip.
const FULL_SCAN_AFTER_MS = 7 * 24 * 60 * 60 * 1000;
const PAGE_SIZE = 1000;
const ADD_BATCH_SIZE = 500;
const MARKER = 'yomiTripAlbum';

if (!API_KEY) throw new Error('IMMICH_API_KEY is not configured');

const request = async (method, path, body) =>
  await this.helpers.httpRequest({
    method,
    url: `${API}${path}`,
    headers: {'x-api-key': API_KEY},
    body,
    json: true,
    timeout: 120000,
  });

const DAY_MS = 24 * 60 * 60 * 1000;
const dayOf = (asset) => String(asset.localDateTime ?? asset.fileCreatedAt).slice(0, 10);
const dayNumber = (day) => Date.parse(`${day}T00:00:00Z`) / DAY_MS;

// Great-circle distance in km. Trips are hundreds of kilometres apart, so the
// spherical approximation is far below the threshold's own fuzziness.
const distanceKm = (aLat, aLon, bLat, bLon) => {
  const rad = (deg) => (deg * Math.PI) / 180;
  const dLat = rad(bLat - aLat);
  const dLon = rad(bLon - aLon);
  const h =
    Math.sin(dLat / 2) ** 2 + Math.cos(rad(aLat)) * Math.cos(rad(bLat)) * Math.sin(dLon / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
};
// }}}

// {{{ Read the library
const state = $getWorkflowStaticData('global');
const now = Date.now();
const lastFullScan = Date.parse(state.lastFullScanAt ?? '');
const fullScan = !Number.isFinite(lastFullScan) || now - lastFullScan >= FULL_SCAN_AFTER_MS || !state.home;

const assets = [];
for (let page = 1; page; ) {
  const response = await request('POST', '/api/search/metadata', {
    withExif: true,
    size: PAGE_SIZE,
    page,
    ...(fullScan
      ? {}
      : {takenAfter: new Date(now - RECENT_WINDOW_DAYS * DAY_MS).toISOString()}),
  });

  assets.push(...(response?.assets?.items ?? []));
  const next = Number(response?.assets?.nextPage);
  page = Number.isFinite(next) && next > page ? next : 0;
}

const located = assets.filter(
  (asset) => Number.isFinite(asset.exifInfo?.latitude) && Number.isFinite(asset.exifInfo?.longitude),
);
// }}}

// {{{ Where home is
const parseOverride = (value) => {
  const [lat, lon] = String(value).split(',').map(Number);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) throw new Error(`IMMICH_HOME_LOCATION is not "lat,lon": ${value}`);
  return {latitude: lat, longitude: lon, label: 'IMMICH_HOME_LOCATION'};
};

const inferHome = () => {
  const places = new Map();
  for (const asset of located) {
    const city = String(asset.exifInfo.city ?? '').trim();
    if (!city) continue;
    const place = places.get(city) ?? {city, days: new Set(), latitudes: [], longitudes: []};
    place.days.add(dayOf(asset));
    place.latitudes.push(asset.exifInfo.latitude);
    place.longitudes.push(asset.exifInfo.longitude);
    places.set(city, place);
  }

  const best = [...places.values()].sort((a, b) => b.days.size - a.days.size)[0];
  if (!best) return null;

  const mean = (values) => values.reduce((sum, value) => sum + value, 0) / values.length;
  return {latitude: mean(best.latitudes), longitude: mean(best.longitudes), label: best.city};
};

const home = HOME_OVERRIDE ? parseOverride(HOME_OVERRIDE) : fullScan ? inferHome() : state.home;
if (!home) throw new Error('No geotagged asset in the library, so home cannot be located');
state.home = home;
// }}}

// {{{ Cut the away days into trips
const away = located
  .filter((asset) => distanceKm(home.latitude, home.longitude, asset.exifInfo.latitude, asset.exifInfo.longitude) > AWAY_KM)
  .sort((a, b) => dayOf(a).localeCompare(dayOf(b)));

const trips = [];
for (const asset of away) {
  const day = dayOf(asset);
  const previous = trips[trips.length - 1];
  if (previous && dayNumber(day) - dayNumber(previous.end) <= TRIP_GAP_DAYS) {
    previous.end = day;
    previous.located.push(asset);
  } else {
    trips.push({start: day, end: day, located: [asset]});
  }
}

const homeCountry = String(
  located.find((asset) => asset.exifInfo?.city === home.label)?.exifInfo?.country ?? '',
).trim();

// Everything shot inside the trip's days joins it, geotagged or not: the
// WhatsApp copies of the same holiday carry no coordinates. Screenshots are
// the one reliably wrong kind, and only the filename says so -- Immich has no
// flag for them.
const isScreenshot = (asset) => /^screenshot/i.test(String(asset.originalFileName ?? ''));
const awayIds = new Set(away.map((asset) => asset.id));
// An asset geotagged at home on a travel day belongs to the day, not to the
// trip, so only the away ones and the coordinate-less ones join.
const candidates = assets.filter(
  (asset) => !isScreenshot(asset) && (awayIds.has(asset.id) || !located.includes(asset)),
);
for (const trip of trips) {
  trip.days = new Set(trip.located.map(dayOf)).size;
  trip.assets = candidates.filter((asset) => dayOf(asset) >= trip.start && dayOf(asset) <= trip.end);
}

const holidays = trips.filter((trip) => trip.days >= MIN_TRIP_DAYS && trip.assets.length >= MIN_TRIP_ASSETS);
// }}}

// {{{ Name a trip
// Abroad, the country is what a person says unless the whole trip sat in one
// or two places: "Cyprus 2026", but "Vienna 2025". At home the country says
// nothing, so the busiest city has to carry it.
const tally = (values) => {
  const counts = new Map();
  for (const value of values) if (value) counts.set(value, (counts.get(value) ?? 0) + 1);
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
};

const placeFor = (trip) => {
  const cities = tally(trip.located.map((asset) => String(asset.exifInfo.city ?? '').trim()));
  const countries = tally(trip.located.map((asset) => String(asset.exifInfo.country ?? '').trim()));
  const [topCity, topCityCount] = cities[0] ?? ['', 0];
  const [topCountry] = countries[0] ?? [''];

  const abroad = topCountry && topCountry !== homeCountry;
  const dominated = cities.length <= 2 && topCityCount >= 0.6 * trip.located.length;
  return (abroad && !dominated ? topCountry : topCity) || topCountry || 'Trip';
};

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const monthOf = (day) => MONTHS[Number(day.slice(5, 7)) - 1];
// }}}

// {{{ Reconcile albums
const albums = await request('GET', '/api/albums?isOwned=true');

const markerOf = (album) => {
  const line = String(album.description ?? '')
    .split('\n')
    .find((candidate) => candidate.includes(`"${MARKER}"`));
  if (!line) return null;
  try {
    const value = JSON.parse(line);
    if (value?.[MARKER] !== 1 || !value.start || !value.end) return null;
    return {start: String(value.start), end: String(value.end)};
  } catch {
    return null;
  }
};

const describe = (trip, name) =>
  `Trip album kept by n8n: ${name}, ${trip.start} to ${trip.end}.\nRename it freely -- the marker below, not the name, is what later runs match on.\n${JSON.stringify({[MARKER]: 1, start: trip.start, end: trip.end})}`;

const managed = albums
  .map((album) => ({album, marker: markerOf(album)}))
  .filter(({marker}) => marker);

let albumsCreated = 0;
let rangesExtended = 0;
let assetsAdded = 0;
let duplicates = 0;
const wantsMerge = [];

for (const trip of holidays) {
  // Match on overlapping days, not on the start date: an ongoing trip grows
  // at both ends as stragglers finish uploading, and a trip whose start
  // shifted by a day must not grow a second album beside the first.
  const overlapping = managed
    .map((entry) => ({
      ...entry,
      overlap:
        Math.min(dayNumber(trip.end), dayNumber(entry.marker.end)) -
        Math.max(dayNumber(trip.start), dayNumber(entry.marker.start)),
    }))
    .filter((entry) => entry.overlap >= -TRIP_GAP_DAYS)
    .sort((a, b) => b.overlap - a.overlap);

  const entry = overlapping[0];
  if (overlapping.length > 1) {
    // Two albums the same trip now spans -- a gap that later uploads filled
    // in. Merging them would delete one, so say so and leave it to a human.
    wantsMerge.push({trip: `${trip.start}..${trip.end}`, albums: overlapping.map(({album}) => album.albumName)});
  }

  const ids = trip.assets.map((asset) => asset.id);
  let target = entry;

  if (!target) {
    // Two holidays in one place in one year need telling apart, and a name a
    // human already used must not be reused for a different trip.
    const taken = new Set(albums.map((album) => album.albumName.toLocaleLowerCase()));
    const place = placeFor(trip);
    const year = trip.start.slice(0, 4);
    const candidateNames = [
      `${place} ${year}`,
      `${place} ${monthOf(trip.start)} ${year}`,
      `${place} ${trip.start}`,
    ];
    const name = candidateNames.find((candidate) => !taken.has(candidate.toLocaleLowerCase())) ?? candidateNames[2];

    // Created empty and filled through the same batched path below: one
    // place where a partial failure is handled, and no cap on trip size.
    const album = await request('POST', '/api/albums', {
      albumName: name,
      description: describe(trip, name),
    });
    albums.push(album);
    target = {album, marker: {start: trip.start, end: trip.end}};
    managed.push(target);
    albumsCreated += 1;
  }

  for (let offset = 0; offset < ids.length; offset += ADD_BATCH_SIZE) {
    const batch = ids.slice(offset, offset + ADD_BATCH_SIZE);
    const results = await request('PUT', `/api/albums/${target.album.id}/assets`, {ids: batch});
    for (const result of results ?? []) {
      if (result.success) assetsAdded += 1;
      else if (result.error === 'duplicate') duplicates += 1;
      else throw new Error(`Immich refused asset ${result.id}: ${result.errorMessage ?? result.error ?? 'unknown error'}`);
    }
  }

  // The name stays whatever a human made it; only the recorded span moves.
  const start = trip.start < target.marker.start ? trip.start : target.marker.start;
  const end = trip.end > target.marker.end ? trip.end : target.marker.end;
  if (start !== target.marker.start || end !== target.marker.end) {
    const grown = {start, end};
    await request('PATCH', `/api/albums/${target.album.id}`, {
      description: describe(grown, target.album.albumName),
    });
    target.marker = grown;
    rangesExtended += 1;
  }
}
// }}}

// The checkpoint moves only once every mutation landed. A crash repeats the
// scan, and the repeat converges through duplicate-safe album additions.
if (fullScan) state.lastFullScanAt = new Date(now).toISOString();
state.lastSuccessfulRunAt = new Date(now).toISOString();

return [
  {
    json: {
      mode: fullScan ? 'full' : 'recent',
      home: home.label,
      assetsExamined: assets.length,
      tripsDetected: holidays.length,
      albumsCreated,
      rangesExtended,
      assetsAdded,
      alreadySorted: duplicates,
      wantsMerge,
    },
  },
];
